const body=$input.first().json.body||$input.first().json;
const curs=[...new Set((body.payments||[]).map(p=>p.currency||'EUR').filter(c=>c!=='EUR'))];
return [{json:{payments:body.payments||[], preset:body.preset||'FR_MICRO_BNC', year:body.year||new Date().getFullYear(), symbols:curs.join(',')||'USD'}}];

// ===== PRESETS (edit/add your country) — amounts in EUR unless stated =====
const PRESETS={
 FR_MICRO_BNC:{label:'France micro-entrepreneur – other services (BNC)', socialRatePct:25.6, thresholds:[{name:'VAT franchise (base)',amount:37500},{name:'VAT franchise (increased: VAT due immediately)',amount:41250},{name:'Micro regime ceiling',amount:83600}]},
 FR_MICRO_BIC_SERVICES:{label:'France micro-entrepreneur – commercial/craft services (BIC)', socialRatePct:21.2, thresholds:[{name:'VAT franchise (base)',amount:37500},{name:'VAT franchise (increased)',amount:41250},{name:'Micro regime ceiling',amount:83600}]},
 UK_SOLE_TRADER:{label:'UK sole trader (VAT registration threshold, GBP)', currency:'GBP', socialRatePct:null, thresholds:[{name:'VAT registration threshold (rolling 12 months)',amount:90000}]},
 CUSTOM:{label:'Custom', socialRatePct:null, thresholds:[{name:'My threshold',amount:50000}]}
};
const WARN_AT=[0.8,0.95];
// ========================================================================
const inp=$('Prepare').first().json; const fx=$input.first().json; const P=PRESETS[inp.preset]||PRESETS.CUSTOM;
const base=P.currency||'EUR';
const toBase=(a,c)=>{ c=c||'EUR'; if(c===base) return a; if(base==='EUR'&&fx.rates&&fx.rates[c]) return a/fx.rates[c]; return null; };
let ytd=0, unconverted=[]; const byMonth={};
for(const p of inp.payments){ if(!p.paidDate||!p.paidDate.startsWith(String(inp.year))) continue; const v=toBase(p.amount,p.currency); if(v===null){unconverted.push(p);continue;} ytd+=v; const m=p.paidDate.slice(0,7); byMonth[m]=(byMonth[m]||0)+v; }
const r2=x=>Math.round(x*100)/100;
const alerts=P.thresholds.map(t=>{const ratio=ytd/t.amount; const level= ratio>=1?'EXCEEDED':ratio>=WARN_AT[1]?'CRITICAL':ratio>=WARN_AT[0]?'WARNING':'OK'; return {threshold:t.name,amount:t.amount,usedPct:r2(ratio*100),remaining:r2(t.amount-ytd),level};});
const months=Object.keys(byMonth).sort(); const last=months[months.length-1];
const social = P.socialRatePct ? r2((byMonth[last]||0)*P.socialRatePct/100) : null;
const worst=alerts.find(a=>a.level!=='OK');
return [{json:{preset:P.label, currency:base, year:inp.year, revenueYTD:r2(ytd), revenueByMonth:Object.fromEntries(months.map(m=>[m,r2(byMonth[m])])), fxDate:fx.date||null,
 lastMonth:last, lastMonthRevenueToDeclare:last?r2(byMonth[last]):0, estimatedSocialContributionsLastMonth:social, alerts, unconverted,
 summary: worst?`⚠️ ${worst.threshold}: ${worst.usedPct}% used (${worst.level}).`:`✅ All thresholds OK (${r2(ytd)} ${base} YTD).`,
 disclaimer:'Estimates only. Verify rates/thresholds yearly on official sources; not tax advice.'}}];
